"""Printed 311–312: bisection algorithm/example and regula-falsi derivation."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path

def secants():
 paths=[];labels=[]
 for j in range(2):
  ox=43+j*275
  def pt(x,y):return(ox+58*x,182-24*y)
  f=(lambda x:(x-3)**2-4) if j==0 else (lambda x:2-x-.25*x*x)
  a=0;b=3;c=a-(a-b)*f(a)/(f(a)-f(b));r=1 if j==0 else 2*(3**.5-1)
  paths.extend([path([pt(-.2,0),pt(3.8,0)]),path([pt(0,-4.5),pt(0,6)]),path([pt(i/80,f(i/80)) for i in range(241)],stroke='#0369a1'),path([pt(a,f(a)),pt(b,f(b))],stroke='#b91c1c')])
  aa,bb=(a,c) if f(a)*f(c)<0 else(c,b);c1=aa-(aa-bb)*f(aa)/(f(aa)-f(bb));paths.append(path([pt(aa,f(aa)),pt(bb,f(bb))],stroke='#b91c1c',dash=True))
  for x,name in [(a,'a₀'),(b,'b₀'),(c,'c₀'),(c1,'c₁')]:
   xx,yy=pt(x,f(x));xx0,yy0=pt(x,0);paths.append(path([(xx,yy),(xx0,yy0)],dash=True));labels.append((xx0-6,yy0+20+(18 if name=='c₁' else 0),name))
   if name in ['a₀','b₀']:labels.append((xx+5,yy-7,'('+name+',f'+name[0]+'₀)'))
  xx,yy=pt(r,0);labels.extend([(xx-5,yy-9,'r'),(ox+220,187,'x'),(ox-6,30,'y')])
 return geometry('Figure 12.2','Figure 12.2 — schematic false-position chord intersections and retained sign-changing brackets',paths,labels,size=(580,320))
ALGORITHM=[paragraph('The given interval [a₀,b₀] is the initial interval at which f(x) must have opposite signs. It brackets the actual root r and its midpoint is:'),eq(r'c_0=\frac{a_0+b_0}{2}'),paragraph('This develops first iterate c₀ through properties 1 or 2. The next interval [a₁,b₁] brackets r, with midpoint c₁=(a₁+b₁)/2 giving the second iterate. Similarly [aₙ,bₙ] is the nth bracket and cₙ=(aₙ+bₙ)/2. It develops the (n−1)th iterate cₙ₋₁ to the actual root in the nth interval. After n iterations, cₙ₋₁ is taken as the desired approximation r≈cₙ₋₁.'),note('The source indexing mixes cₙ and cₙ₋₁. With [a₀,b₀] initial, iteration j evaluates cⱼ=(aⱼ+bⱼ)/2 and then retains [aⱼ₊₁,bⱼ₊₁]. After n midpoint evaluations, the last evaluated midpoint is cₙ₋₁; the final bracket width is (b₀−a₀)/2ⁿ. Its midpoint cₙ, if computed, has error at most (b₀−a₀)/2^(n+1). Endpoint roots should be accepted before requiring strict opposite signs.')]
EX1_START=[heading('Example 1'),paragraph('Perform two iterations of bisection to approximate the root of f(x)=sin x−e^(−x), with x in radians, in [0.5,0.7].'),heading('Solution'),paragraph('Set [a₀,b₀]=[0.5,0.7] and compute:'),eq(r'f(a_0)=f(0.5)=\sin0.5-e^{-0.5}=-0.127<0'),eq(r'f(b_0)=f(0.7)=\sin0.7-e^{-0.7}=+0.148>0'),paragraph('The values have opposite signs, so a root lies in the interval. The initial midpoint is:'),eq(r'c_0=\frac{a_0+b_0}{2}=\frac{0.5+0.7}{2}=0.6'),eq(r'f(a_0)=-0.127<0,\quad f(b_0)=+0.148>0,\quad f(c_0)=f(0.6)=+0.016>0'),paragraph('f(a₀) and f(c₀) have opposite signs. Retain [0.5,0.6], discard b₀=0.7, and reset [a₁,b₁]=[0.5,0.6]. The next midpoint is:'),eq(r'c_1=\frac{a_1+b_1}{2}=\frac{0.5+0.6}{2}=0.55'),heading('Remember'),paragraph('To find an approximate root of f(x)=0 in [a,b], proceed only if f(x) is continuous and f(a),f(b) have opposite signs.')]
EX1_END=[eq(r'f(a_1)=f(0.5)=-0.127<0,\quad f(c_1)=f(0.55)=-0.054<0,\quad f(b_1)=f(0.6)=+0.016>0'),paragraph('f(b₁),f(c₁) have opposite signs, so retain [0.55,0.6], discard a₁=0.5 and set [a₂,b₂]=[0.55,0.6]. After the second iteration, c₁=0.55 is declared the approximate root r≈c₁. The source next states:'),eq(r'f(0.055)=-0.054'),note('The last source argument 0.055 is a decimal-place typo: f(0.55)≈−0.05426155, whereas f(0.055)≈−0.89151287. The two evaluated midpoints are 0.6 and 0.55; the final sign-changing bracket is [0.55,0.6]. The last midpoint 0.55 has a bracket error bound 0.05. If the final bracket midpoint 0.575 is also calculated, its bound is 0.025, but it is not one of the two source midpoint iterations. The derivative cos x+e^(−x)>0 throughout the bracket ensures this root is unique there.')]
REGULA=[heading('(b) Regula-Falsi method'),paragraph('The next bracketing method is regula-falsi, developed because bisection converges at a fairly slow speed. Assume f(a),f(b) have opposite signs. Instead of the midpoint, the next iterate is the x-axis intersection (c,0) of the line through (a,f(a)),(b,f(b)).'),eq(r'\frac{y-f(a)}{x-a}=\frac{f(b)-f(a)}{b-a}'),eq(r'\frac{0-f(a)}{c-a}=\frac{f(b)-f(a)}{b-a},\quad(x,y)=(c,0)'),eq(r'c=a-\frac{(a-b)f(a)}{f(a)-f(b)}','i'),paragraph('Analyze: i. If f(a),f(c) have opposite signs, the root lies in [a,c]; discard b. ii. If f(c),f(b) have opposite signs, the root lies in [c,b]; discard a. iii. If f(c)=0, c is an approximate root. Figure 12.2 illustrates the process.'),secants(),note('Continuity and a genuine sign-changing bracket are required. The denominator f(a)−f(b) is nonzero under strict opposite signs, and the chord intersection lies inside the bracket. Unlike bisection, classical false-position can keep one endpoint for many iterations and need not halve the width or converge faster. If f(c)=0 exactly, c is an exact root. The native diagrams are schematic source geometry, with the secant construction calculated consistently.')]
PAGES=[page('160_page_1.jpg',311,ALGORITHM+EX1_START),page('160_page_2.jpg',312,EX1_END+REGULA)]
for p in PAGES:p.update(title='INTRODUCTION TO NUMERICAL METHODS',visualStatus='Full native midpoint algorithm, source bisection example and false-position chord diagrams',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':160,'side':'left' if p['page']==311 else 'right','reason':'All midpoint values, bracket updates, source decimal typo and chord formula visually checked'})
EXAMPLES=[{'num':'1','title':'Two Bisection Iterations','question':'Perform two bisection iterations for sin x−e^(−x)=0 on [0.5,0.7], with x in radians.','steps':['f is continuous, f(0.5)≈−0.12710512 and f(0.7)≈0.14763238, so the initial interval brackets a root.','First midpoint c₀=(0.5+0.7)/2=0.6. Evaluate f(0.6)≈0.01583084>0.','Retain [0.5,0.6] because its endpoints have opposite signs.','Second midpoint c₁=(0.5+0.6)/2=0.55. Evaluate f(0.55)≈−0.05426155<0.','Retain [0.55,0.6]. Thus the source two-iteration approximation is the last evaluated midpoint 0.55.','The final bracket width is 0.05. Its midpoint 0.575 would have error at most 0.025 if additionally computed; the last evaluated 0.55 is within 0.05 of the bracketed root.','The source f(0.055)=−0.054 is a decimal typo: the −0.054 value belongs to 0.55. Maintain the distinction between a residual and root error.'],'answer':'Evaluated midpoints 0.6,0.55; final bracket [0.55,0.6]; source approximation r≈0.55.','progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':311,'jpg':'160_page_1.jpg'},{'page':312,'jpg':'160_page_2.jpg','verification':'Both midpoint steps and source decimal typo checked'}]}]
